"""Diff two memory dumps of the same target: find identical regions across runs,
then look for bytecode-like blobs (low byte-value spread, plausible sizes).
"""
import json, sys
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")

def load(tag):
    d = (ROOT / f'_work/t1/{tag}').read_bytes()
    idx = json.loads((ROOT / f'_work/t1/{tag}.idx.json').read_text())
    return d, idx

d1, i1 = load('dump1')
d2, i2 = load(sys.argv[1] if len(sys.argv) > 1 else 'dump2')

def get(d, idx, addr):
    for r in idx:
        if r['addr'] == addr:
            return d[r['off']:r['off']+r['size']]
    return None

print(f'dump1 regions={len(i1)} dump2 regions={len(i2)}')
m2 = {r['addr']: r for r in i2}
shared = []
for r in i1:
    if r['addr'] in m2 and m2[r['addr']]['size'] == r['size']:
        b1 = d1[r['off']:r['off']+r['size']]
        b2 = d2[m2[r['addr']]['off']:m2[r['addr']]['off']+r['size']]
        if b1 == b2:
            shared.append((r['addr'], r['size']))
print(f'shared identical regions: {len(shared)}, total {sum(s for _,s in shared)} bytes')
for addr, size in shared:
    if size >= 4096:
        print(f'  addr={addr:#x} size={size}')

# in shared regions, find bytecode-like stretches: entropy per 4KB block, small-byte fraction
import math
from collections import Counter
def stats(b):
    c = Counter(b); n = len(b)
    ent = -sum((v/n)*math.log2(v/n) for v in c.values()) if n else 0
    small = sum(v for k, v in c.items() if k < 0x20) / n if n else 0
    return ent, small

print('== large shared regions detail ==')
for addr, size in shared:
    if size < 2048:
        continue
    b1 = get(d1, i1, addr)
    # scan 1024-byte windows for low-entropy / small-byte-heavy windows
    wins = []
    for off in range(0, size - 1024, 1024):
        ent, small = stats(b1[off:off+1024])
        if small > 0.5 or ent < 5.0:
            wins.append((off, round(ent,2), round(small,2)))
    if wins:
        print(f'addr={addr:#x} size={size} candidate windows (off,ent,small): {wins[:8]}')
